265:   function mergeDefaults(saved, defaults) {
266:     if (Array.isArray(defaults)) return Array.isArray(saved) ? saved : defaults;
267:     if (defaults && typeof defaults === "object") {
268:       const out = { ...defaults };
269:       if (saved && typeof saved === "object") {
270:         for (const key of Object.keys(saved)) {
271:           out[key] = key in defaults ? mergeDefaults(saved[key], defaults[key]) : saved[key];
272:         }
273:       }
274:       return out;
275:     }
276:     return saved === undefined ? defaults : saved;
277:   }
