418: .agent-card::before { content: ""; position: absolute; inset: 0 0 auto 0; height: 2px; background: linear-gradient(90deg, var(--accent, var(--green)), transparent 70%); opacity: .7; }
419: .agent-card:hover { transform: translateY(-2px); border-color: color-mix(in srgb, var(--accent, var(--green)) 32%, transparent); box-shadow: 0 14px 34px rgba(0,0,0,.34); }
420: .agent-top { display: flex; align-items: center; gap: 10px; }
