432: .room-card { position: relative; padding: 16px; min-height: 166px; display: flex; flex-direction: column; border-radius: 12px; border: 1px solid var(--line); background:
433:   radial-gradient(160px 120px at 100% 0%, color-mix(in srgb, var(--accent, var(--green)) 12%, transparent), transparent 70%),
