459: /* ---------- Tasks ---------- */
460: .task-layout { display: grid; grid-template-columns: minmax(0,1.5fr) minmax(270px, .8fr); gap: 18px; align-items: start; }
461: .task-summary { display: grid; grid-template-columns: repeat(3, 1fr); gap: 9px; margin-bottom: 14px; }
462: .task-sum { padding: 11px 12px; border-radius: 9px; border: 1px solid var(--line); background: rgba(255,255,255,0.025); }
463: .task-sum .n { font-family: var(--font-brand); font-size: 20px; color: var(--c, var(--green)); }
464: .task-sum .l { font-size: 9.5px; letter-spacing: 1.2px; text-transform: uppercase; color: var(--muted); margin-top: 1px; }
465: .task-filters { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 11px; }
466: .task-list { display: flex; flex-direction: column; gap: 7px; }
467: .task-row { display: flex; align-items: flex-start; gap: 10px; padding: 11px 12px; border-radius: 9px; border: 1px solid var(--line); background: linear-gradient(150deg, rgba(18,29,34,0.7), rgba(8,14,17,0.9)); transition: all 150ms ease; }
