471: .check-btn { width: 20px; height: 20px; border-radius: 6px; border: 1px solid var(--line-strong); background: rgba(255,255,255,0.025); display: grid; place-items: center; flex: 0 0 auto; margin-top: 1px; transition: all 150ms ease; }
472: .check-btn .ico { width: 12px; height: 12px; color: #041004; stroke-width: 3; opacity: 0; }
473: .check-btn:hover { border-color: var(--green); }
474: .task-row.done .check-btn { background: var(--green); border-color: var(--green); box-shadow: 0 0 10px rgba(141,255,72,0.3); }
