482: .task-del .ico { width: 13px; height: 13px; }
483: .quick-add { display: flex; gap: 7px; margin-top: 12px; }
484: .quick-add .input { flex: 1; }
485: .quick-add .select { width: 110px; flex: 0 0 auto; }
