487: .task-board { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 10px; }
488: .task-col { border: 1px solid var(--line); border-radius: 11px; background: rgba(255,255,255,0.018); padding: 10px; min-height: 160px; }
489: .task-col h5 { display: flex; align-items: center; justify-content: space-between; font-size: 10px; letter-spacing: 1.4px; text-transform: uppercase; color: var(--muted); margin-bottom: 8px; }
490: .task-col h5 .count { font-family: var(--font-mono); }
