494: /* ---------- Chat ---------- */
495: .chat-layout { display: grid; grid-template-columns: 230px minmax(0, 1fr); gap: 14px; height: calc(100vh - 190px); min-height: 500px; }
496: .chat-side { display: flex; flex-direction: column; }
497: .chat-side .panel-head { padding: 13px 14px; }
498: .chat-new { margin: 10px; }
499: .convo-list { flex: 1; overflow-y: auto; padding: 4px 8px 8px; }
500: .convo { display: flex; align-items: center; gap: 9px; padding: 9px 10px; border-radius: 8px; font-size: 12.5px; color: var(--text-dim); cursor: pointer; border: 1px solid transparent; }
501: .convo:hover { background: rgba(255,255,255,0.03); }
502: .convo.active { background: rgba(141,255,72,0.08); border-color: rgba(141,255,72,0.16); color: var(--text); }
503: .convo .ico { width: 15px; height: 15px; color: var(--muted); }
