508: .chat-head-copy strong { display: block; font-size: 14px; }
509: .chat-head-copy small { font-size: 10.5px; color: var(--muted); }
510: .chat-head .badge { margin-left: auto; }
511: .chat-messages { flex: 1; overflow-y: auto; padding: 18px 18px 10px; display: flex; flex-direction: column; gap: 14px; }
512: .msg { display: flex; gap: 9px; max-width: 86%; }
513: .msg.user { align-self: flex-end; flex-direction: row-reverse; }
514: .msg-ava { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; flex: 0 0 auto; font-size: 9px; font-weight: 700; border: 1px solid var(--line); color: var(--green); background: rgba(141,255,72,0.08); }
515: .msg.user .msg-ava { color: var(--cyan); background: rgba(49,216,255,0.08); border-color: rgba(49,216,255,0.24); }
516: .msg-bubble { padding: 10px 13px; border-radius: 11px; font-size: 13.5px; line-height: 1.55; color: var(--text-dim); background: rgba(255,255,255,0.035); border: 1px solid var(--line); white-space: pre-wrap; overflow-wrap: anywhere; }
517: .msg.user .msg-bubble { background: rgba(49,216,255,0.075); border-color: rgba(49,216,255,0.18); color: #d9f7ff; }
518: .msg-bubble code { font-family: var(--font-mono); font-size: 12px; background: rgba(0,0,0,0.35); border: 1px solid var(--line); border-radius: 4px; padding: 1px 4px; color: var(--green); }
519: .msg-bubble pre { margin: 8px 0 0; padding: 10px; border-radius: 7px; background: rgba(0,0,0,0.42); border: 1px solid var(--line); overflow-x: auto; }
520: .msg-bubble pre code { border: 0; padding: 0; background: none; }
521: .msg-meta { display: flex; align-items: center; gap: 7px; margin-top: 5px; font-size: 9px; color: var(--muted); }
522: .msg.user .msg-meta { justify-content: flex-end; }
523: .typing { display: inline-flex; gap: 4px; align-items: center; padding: 4px 0; }
