525: .typing i:nth-child(2) { animation-delay: .16s; }
526: .typing i:nth-child(3) { animation-delay: .32s; }
527: @keyframes typing { 0%,60%,100% { opacity: .25; transform: translateY(0); } 30% { opacity: 1; transform: translateY(-3px); } }
528: .chat-composer { padding: 11px 14px 14px; border-top: 1px solid var(--line); }
529: .composer-box { display: flex; align-items: flex-end; gap: 8px; padding: 8px 8px 8px 12px; border-radius: 11px; border: 1px solid var(--line); background: rgba(2,6,8,0.55); }
530: .composer-box:focus-within { border-color: rgba(141,255,72,0.4); box-shadow: 0 0 0 3px rgba(141,255,72,0.06); }
531: .composer-box textarea { flex: 1; background: none; border: 0; resize: none; outline: none; color: var(--text); font-size: 14px; line-height: 1.5; min-height: 24px; max-height: 120px; padding: 5px 0; }
532: .composer-box .btn { flex: 0 0 auto; }
533: .composer-meta { display: flex; align-items: center; gap: 8px; margin-top: 7px; font-size: 9.5px; color: var(--muted); flex-wrap: wrap; }
534: .chat-select { padding: 4px 22px 4px 8px; font-size: 10px; border-radius: 6px; border: 1px solid var(--line); background-color: transparent; }
