536: /* ---------- Notes ---------- */
537: .note-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 11px; }
538: .note-card { position: relative; padding: 14px; border-radius: 10px; border: 1px solid var(--line); background: linear-gradient(150deg, rgba(18,29,34,0.82), rgba(8,14,17,0.94)); min-height: 130px; display: flex; flex-direction: column; transition: all 170ms ease; }
539: .note-card:hover { transform: translateY(-2px); border-color: rgba(141,255,72,0.28); }
540: .note-card::before { content: ""; position: absolute; top: 0; left: 14px; right: 14px; height: 1px; background: linear-gradient(90deg, transparent, var(--accent, var(--green)), transparent); opacity: .45; }
541: .note-card h4 { font-size: 14px; padding-right: 26px; }
542: .note-card p { font-size: 12px; color: var(--muted); line-height: 1.5; margin-top: 7px; white-space: pre-wrap; overflow-wrap: anywhere; }
543: .note-foot { display: flex; align-items: center; gap: 7px; margin-top: auto; padding-top: 12px; font-size: 9.5px; color: var(--muted); }
544: .note-actions { position: absolute; top: 9px; right: 9px; display: flex; gap: 2px; opacity: 0; transition: opacity 150ms ease; }
545: .note-card:hover .note-actions { opacity: 1; }
