549: /* ---------- Settings ---------- */
550: .settings-grid { display: grid; grid-template-columns: minmax(0,1.35fr) minmax(280px, .85fr); gap: 18px; align-items: start; }
551: .settings-section { padding: 16px 17px; border-bottom: 1px solid var(--line); }
552: .settings-section:last-child { border-bottom: 0; }
553: .settings-section h4 { display: flex; align-items: center; gap: 8px; font-size: 11px; letter-spacing: 1.6px; text-transform: uppercase; color: var(--text-dim); margin-bottom: 13px; }
554: .settings-section h4 .ico { width: 15px; height: 15px; color: var(--green); }
555: .setting-row { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 10px 0; border-bottom: 1px dashed rgba(255,255,255,0.05); }
556: .setting-row:last-child { border-bottom: 0; }
557: .setting-copy { min-width: 0; }
558: .setting-copy strong { display: flex; align-items: center; gap: 6px; font-size: 13.5px; font-weight: 600; }
559: .setting-copy small { display: block; font-size: 10.5px; color: var(--muted); margin-top: 1px; line-height: 1.4; }
560: .setting-row .input, .setting-row .select { max-width: 250px; }
561: .switch { position: relative; width: 42px; height: 23px; flex: 0 0 auto; border-radius: 20px; border: 1px solid var(--line-strong); background: rgba(255,255,255,0.05); transition: all 180ms ease; }
562: .switch::after { content: ""; position: absolute; top: 2px; left: 2px; width: 17px; height: 17px; border-radius: 50%; background: var(--muted); transition: all 180ms ease; }
563: .switch.on { background: rgba(141,255,72,0.2); border-color: rgba(141,255,72,0.5); box-shadow: 0 0 12px rgba(141,255,72,0.14); }
564: .switch.on::after { left: 21px; background: var(--green); box-shadow: 0 0 8px rgba(141,255,72,0.6); }
565: .limit-row { display: flex; align-items: center; gap: 8px; }
566: .limit-row .input { width: 80px; text-align: center; }
