568: /* ---------- Terminal ---------- */
569: .terminal-wrap { border-radius: 13px; border: 1px solid var(--line); background: rgba(2,7,9,0.9); overflow: hidden; box-shadow: var(--shadow); }
570: .terminal-head { display: flex; align-items: center; gap: 8px; padding: 9px 13px; background: rgba(255,255,255,0.025); border-bottom: 1px solid var(--line); }
571: .term-dots { display: flex; gap: 5px; margin-right: 6px; }
572: .term-dots span { width: 8px; height: 8px; border-radius: 50%; background: var(--red); }
573: .term-dots span:nth-child(2) { background: var(--yellow); }
574: .term-dots span:nth-child(3) { background: var(--green); }
575: .terminal-head strong { font-family: var(--font-mono); font-size: 11px; color: var(--text-dim); font-weight: 400; }
