588: .term-key { font-family: var(--font-mono); font-size: 9.5px; color: var(--text-dim); border: 1px solid var(--line); border-bottom-width: 2px; border-radius: 5px; padding: 3px 8px; background: rgba(255,255,255,0.025); }
